script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/report/operating`;

await step('Mở màn hình Số liệu vận hành', async () => {
  if (!page.url().includes(`/${phanHe}/report/operating`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  await page.getByText('A. Theo số lượng phiếu').first().waitFor({ timeout: 20000 });
});

await step('Kiểm tra bộ lọc Thời gian, Phân loại phiếu, Vùng miền', async () => {
  assert(await page.locator('.hrv-date-time-picker').first().isVisible().catch(() => false), 'Không thấy bộ chọn Thời gian');
  assert(await page.getByText('Chọn Phân loại phiếu').first().isVisible().catch(() => false), 'Không thấy bộ lọc Phân loại phiếu');
  assert(await page.getByText('Vùng miền', { exact: true }).first().isVisible().catch(() => false), 'Không thấy bộ lọc Vùng miền');
});

await step('Kiểm tra 5 nhóm báo cáo A, B, C, D, E', async () => {
  const txt = await page.locator('body').innerText();
  for (const section of [
    'A. Theo số lượng phiếu',
    'B. Theo thời gian tiếp nhận',
    'C. Theo thời gian xử lý phiếu',
    'D. Theo mức độ hài lòng',
    'E. Theo phân loại phiếu'
  ]) {
    assert(txt.includes(section), 'Thiếu nhóm báo cáo: ' + section);
  }
  for (const metric of [
    'Số phiếu tiếp nhận',
    'Số phiếu hoàn tất xử lý',
    'Tỉ lệ phiếu đạt SLAs',
    'Thời gian xử lý phiếu trung bình'
  ]) {
    assert(txt.includes(metric), 'Thiếu chỉ số: ' + metric);
  }
  ctx.log('Báo cáo Số liệu vận hành hiển thị đầy đủ 5 nhóm A-E.');
});
